const invoiceCreditNotes = `-- name: InvoiceCreditNotes :many
SELECT id, number, note_date, status, total, applied
FROM sales.credit_notes
WHERE company_id = $1 AND invoice_id = $2
ORDER BY note_date, number
`

type InvoiceCreditNotesParams struct {
	CompanyID uuid.UUID
	InvoiceID uuid.UUID
}

type InvoiceCreditNotesRow struct {
	ID       uuid.UUID
	Number   string
	NoteDate civil.Date
	Status   string
	Total    money.Amount
	Applied  money.Amount
}

func (q *Queries) InvoiceCreditNotes(ctx context.Context, arg InvoiceCreditNotesParams) ([]InvoiceCreditNotesRow, error) {
	rows, err := q.db.Query(ctx, invoiceCreditNotes, arg.CompanyID, arg.InvoiceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []InvoiceCreditNotesRow
	for rows.Next() {
		var i InvoiceCreditNotesRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.NoteDate,
			&i.Status,
			&i.Total,
			&i.Applied,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

